    "id": "bullet-chart",
    "title": "Bullet Chart",
    "category": "Comparison",
    "description": "A bullet chart is a compact gauge: a single measure bar sits inside graded background bands, with a short marker showing a target. You read whether the measure has cleared its target and which qualitative band (poor, okay, good) it falls in. It packs a KPI's actual, target, and context into one thin strip.",
    "whenToUse": "When you need to show a single metric against a target and qualitative ranges compactly, as in a dashboard or scorecard.",
    "dataNeeded": [
      {
        "name": "Measured value",
        "unit": "unitless"
      },
      {
        "name": "Target value",
        "unit": "unitless"
      },
      {
        "name": "Range thresholds",
        "unit": "unitless"
      }
    ],
