    "id": "dot-plot",
    "title": "Cleveland Dot Plot",
    "category": "Comparison",
    "description": "A Cleveland dot plot marks each category's value with a single dot placed along a common value axis, one row per category. Because position along a line is one of the most accurate visual cues, small differences between categories are easier to judge than with bars. Rows are usually sorted so the ranking is immediate.",
    "whenToUse": "When you need precise comparison of one value across many categories and want to avoid heavy bars, especially when differences are subtle.",
    "dataNeeded": [
      {
        "name": "Category",
        "unit": "category"
      },
      {
        "name": "Value",
        "unit": "%/day"
      }
    ],
