    "id": "marimekko",
    "title": "Marimekko (Mosaic) Chart",
    "category": "Composition",
    "description": "A Marimekko, or mosaic, chart is a stacked bar chart where the bar widths also vary to encode a second dimension, so every tile's area is meaningful. Column width shows one category's overall share while each column's internal stacking shows a second breakdown, letting you read two categorical proportions at once. The result is a patchwork of rectangles whose areas sum to the whole.",
    "whenToUse": "Use it to show a two-way part-to-whole breakdown — for instance market segments (width) each split by product mix (height) — in a single space-filling picture.",
    "dataNeeded": [
      {
        "name": "Column category (sets width)",
        "unit": "category"
      },
      {
        "name": "Segment category (sets height)",
        "unit": "category"
      },
      {
        "name": "Value per combination",
        "unit": "numeric"
      }
    ],
